<template><BtgPageContainer as="article" aria-labelledby="verification-title"><div v-if="state==='loading'" role="status"><h1 id="verification-title">Checking certificate…</h1></div><div v-else-if="state==='missing'"><h1 id="verification-title">Certificate unavailable</h1><p>This certificate is not recorded.</p></div><div v-else-if="state==='error'" role="alert"><h1 id="verification-title">Verification unavailable</h1><BtgButton @click="load">Try again</BtgButton></div><template v-else><h1 id="verification-title">Certificate verification</h1><p role="status">{{ certificate.status==='ACTIVE'?`This certificate was issued by ${certificate.issuer.name} and is recorded as active.`:'This certificate is recorded as revoked.' }}</p><dl><div><dt>Achievement</dt><dd>{{ certificate.achievement.title }}</dd></div><div><dt>Version</dt><dd>{{ certificate.achievement.version }}</dd></div><div><dt>Issued</dt><dd>{{ format(certificate.issuedAt) }}</dd></div><div><dt>Criteria</dt><dd>{{ certificate.achievement.criteria }}</dd></div></dl></template></BtgPageContainer></template><script setup lang="ts">import{ref,watch}from'vue';import{useRoute}from'vue-router';import{APIProblemError}from'../api/client';import BtgPageContainer from'../components/BtgPageContainer.vue';import BtgButton from'../components/BtgButton.vue';import{getPublicCertificate,type PublicCertificate}from'../courses/certificates';const route=useRoute(),state=ref('loading'),certificate=ref<PublicCertificate>({} as PublicCertificate);let generation=0;watch(()=>route.params.certificateId,load,{immediate:true});async function load(){const id=String(route.params.certificateId||''),n=++generation;state.value='loading';try{const x=await getPublicCertificate(id);if(n!==generation)return;certificate.value=x;state.value='ready'}catch(e){if(n!==generation)return;state.value=e instanceof APIProblemError&&e.status===404?'missing':'error'}}function format(v:string){return new Intl.DateTimeFormat('en',{dateStyle:'medium'}).format(new Date(v))}</script>
